// H 系列站点健康巡检：拉 sitemap → 逐 URL 查状态/耗时 → 页面内链接扫描 → 首页品牌校验 → 汇总
// 结果由下一节点回传控制台 /h/ingest。webhook 已立即响应，此处为后台执行。
//
// 2026-08-01 补页面内链接扫描：此前只验 sitemap 名单上的 URL 通不通，从不打开
// 页面看里面的链接，所以页头写死的死链（6 个 Flatsome 演示遗留的假社交图标）
// 挂了很久一条没报——那些地址从来不进 sitemap。现在逐页巡检时顺手把 body 里的
// 链接/图片提出来验，零额外抓取。
const helpers = this.helpers;
const input = $input.first().json;
const body = input.body || input;
const runId = body.run_id || null;
// 定时触发时没有 payload（webhook 那条路才有），回报地址得自己兜底。
// 控制台侧默认就是这个（H_CALLBACK_BASE 缺省 http://console_backend:8000），
// 同 docker 网络内直连，不绕公网也就不吃 Nginx 那层限流。
const ingestUrl = body.ingest_url || 'http://console_backend:8000/api/app/h/ingest';

const SITE = 'https://barongyekhna.com';
const SLOW = 3000;          // 慢页阈值 ms
const CAP = 150;            // 单轮最多巡检 URL 数（sitemap 名单）
// 页面内链接验证上限。真正的刹车是下面的 DEADLINE_MS 时间预算,这里设高一点
// 让时间说了算：实测 193 个有效候选、验 120 条只用了 117s/230s 预算,CAP 反而成了
// 瓶颈——白漏 73 个链接。漏报正是这个哨兵要解决的问题,不该被一个拍脑袋的数字卡住。
const LINK_CAP = 300;
const LINK_GAP_MS = 400;    // 站在 WP.com：实测并发 6 就 429，靠间隔压住
// ⚠️ n8n task runner 的沙箱有 300s 硬超时（base-runner-config.js: taskTimeout=300），
//    超时整轮报错、什么都不回报。这里自设 230s 软预算，到点就停止链接验证并把
//    没验完的数量记进 links_truncated，保证任何情况下都能正常回报。
const DEADLINE_MS = 230000;
const BRAND = 'Barong Yekhna';
const T0 = Date.now();
// 429=限速、503=暂时不可用,都是「等会儿再来就好」,不是死链。哨兵自己高频巡检时最容易
// 撞上(2026-08-02 实测一轮报了 8 条假 429 死链),记成死链会让真告警被假阳性淹没。
const RETRYABLE = new Set([429, 503]);
// 慢页只测一次就报 = 网络抖一下、或者有人正在压站，就误报一条。
// 2026-08-02 实测:某指南页被报 3201ms(超阈值 200ms)，但那正是有人并发扫全站的时候，
// 隔几秒复测是 1.5s —— 页面根本不慢。假警报的代价是人得自己判断真假，久了就不看了。
// 现在超阈值先复测，**连最快的一次都超阈值**才算真慢。
const SLOW_RECHECKS = 2;        // 超阈值后补测几次
const SLOW_RECHECK_GAP = 2500;  // 每次之间等多久（等抖动过去）
let rateLimited = 0;
let extraGap = 0;   // 撞到限速就自动放慢,越撞越慢

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- URL 工具 ----
// ⚠️ 沙箱里没有 URL 构造器。n8n task runner 只注入 Buffer / setTimeout / setInterval /
//    setImmediate / clear* / btoa / atob / TextEncoder / TextDecoder / FormData
//    （见 js-task-runner.js 的 getNativeVariables），URL 是 Node/Web API 不在其中。
//    2026-08-01 用 new URL() 写过一版，整轮直接 ReferenceError 挂掉。别再用。
function originOf(u) {
  const m = /^(https?:)\/\/([^/?#]+)/i.exec(String(u));
  return m ? { proto: m[1].toLowerCase(), host: m[2].toLowerCase() } : null;
}
function resolveUrl(href, base) {
  let h = String(href).trim();
  if (!h) return '';
  const hi = h.indexOf('#');
  if (hi >= 0) h = h.slice(0, hi);
  if (!h) return '';
  if (/^https?:\/\//i.test(h)) return h;
  const b = originOf(base);
  if (!b) return '';
  const origin = b.proto + '//' + b.host;
  if (h.slice(0, 2) === '//') return b.proto + h;
  if (h.charAt(0) === '/') return origin + h;
  // 相对路径：先摘掉查询串，再按 base 所在目录拼，最后归一 ./ 与 ../
  let query = '';
  const qi = h.indexOf('?');
  if (qi >= 0) { query = h.slice(qi); h = h.slice(0, qi); }
  let bpath = String(base).slice(origin.length);
  const bq = bpath.search(/[?#]/);
  if (bq >= 0) bpath = bpath.slice(0, bq);
  bpath = bpath.replace(/[^/]*$/, '');
  const joined = bpath + h;
  const segs = [];
  for (const s of joined.split('/')) {
    if (s === '' || s === '.') continue;
    if (s === '..') { segs.pop(); continue; }
    segs.push(s);
  }
  const trailing = joined.slice(-1) === '/' ? '/' : '';
  return origin + '/' + segs.join('/') + trailing + query;
}
function norm(u) {
  let s = String(u);
  const i = s.indexOf('#');
  if (i >= 0) s = s.slice(0, i);
  const o = originOf(s);
  if (!o) return s;
  return o.proto + '//' + o.host + s.slice(s.indexOf('//') + 2 + o.host.length);
}
const HOST = (originOf(SITE) || {}).host || '';
const isInternal = (u) => { const o = originOf(u); return !!o && o.host === HOST; };

async function grab(url, tmo) {
  const t = Date.now();
  try {
    const r = await helpers.httpRequest({
      method: 'GET', url, timeout: tmo || 15000,
      returnFullResponse: true, ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': 'BarongYekhna-HealthBot/1.0' },
    });
    let b = r.body;
    if (typeof b !== 'string') { try { b = JSON.stringify(b); } catch (e) { b = ''; } }
    return { status: r.statusCode || 0, ms: Date.now() - t, body: b };
  } catch (e) {
    // String(e) 对普通对象会得到 "[object Object]",拿不到 ENOTFOUND 之类的错误码,
    // 而站外死链判定要靠错误码区分「域名不存在」和「一时连不上」。
    const code = e && e.code ? String(e.code) : '';
    const msg = e && e.message ? String(e.message) : String(e);
    return { status: 0, ms: Date.now() - t, body: '', err: ((code ? code + ' ' : '') + msg).slice(0, 140) };
  }
}
const locs = (xml) => [...String(xml).matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1].trim());

// ---- 链接提取 ----
// ⚠️ href 前必须有 (?<![\w-]) 负向断言：否则 Jetpack 表单的
//    data-wp-bind--href="context.item.anchor" 会被当成真链接（那是 Interactivity
//    API 的运行时绑定属性，浏览器里根本没有 href 属性）。2026-08-01 误报过。
const A_RE = /<a\b[^>]*?(?<![\w-])href\s*=\s*["']([^"']+)["']/gi;
const IMG_RE = /<img\b[^>]*?(?<![\w-])src\s*=\s*["']([^"']+)["']/gi;
const SRCSET_RE = /<(?:img|source)\b[^>]*?(?<![\w-])srcset\s*=\s*["']([^"']+)["']/gi;

function unesc(s) {
  return String(s)
    .replace(/&amp;/gi, '&').replace(/&#0?38;/g, '&')
    .replace(/&quot;/gi, '"').replace(/&#0?39;/g, "'")
    .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');
}

function extractLinks(html, pageUrl) {
  const out = [];
  const push = (raw, kind) => {
    const h = unesc(raw).trim();
    if (!h || h.charAt(0) === '#') return;
    // ⚠️ 白名单而非黑名单:任何 "scheme:" 形式且不是 http(s) 的一律跳过。
    //    2026-08-01 用黑名单漏了 whatsapp://send?text=... —— 分享按钮的自定义协议
    //    被当成相对路径,拼出 20 条 https://站点/产品页/whatsapp:/send?text=... 假 404。
    //    新增协议(intent://、fb-messenger:// 等)以后不必再逐个补。
    if (/^[a-z][a-z0-9+.-]*:/i.test(h) && !/^https?:/i.test(h)) return;
    const abs = resolveUrl(h, pageUrl);
    if (abs && /^https?:\/\//i.test(abs)) out.push({ u: abs, kind: kind });
  };
  let m;
  A_RE.lastIndex = 0; while ((m = A_RE.exec(html)) !== null) push(m[1], 'a');
  IMG_RE.lastIndex = 0; while ((m = IMG_RE.exec(html)) !== null) push(m[1], 'asset');
  SRCSET_RE.lastIndex = 0;
  while ((m = SRCSET_RE.exec(html)) !== null) {
    // ⚠️ srcset 不能直接按逗号拆：data:image/svg+xml;base64,XXX 里 base64 前那个
    //    逗号会把占位图拆成两段，后半段被当成相对路径 → 假 404。先整段剔除 data: URI。
    const cleaned = String(m[1]).replace(/data:[^\s,]*,[A-Za-z0-9+/=]*/gi, ' ');
    cleaned.split(',').forEach((part) => {
      const cand = part.trim().split(/\s+/)[0];
      if (cand) push(cand, 'asset');
    });
  }
  return out;
}

// ---- 1. sitemap ----
let urls = [], sitemapOk = true;
const idx = await grab(SITE + '/wp-sitemap.xml');
if (idx.status >= 200 && idx.status < 300 && idx.body) {
  for (const sub of locs(idx.body)) {
    if (!/\.xml/i.test(sub)) { urls.push(sub); continue; }
    const s = await grab(sub);
    if (s.body) locs(s.body).forEach((u) => urls.push(u));
  }
} else {
  const sm2 = await grab(SITE + '/sitemap.xml');
  if (sm2.status >= 200 && sm2.status < 300 && sm2.body) {
    locs(sm2.body).forEach((u) => { if (!/\.xml/i.test(u)) urls.push(u); });
  } else { sitemapOk = false; }
}
urls = [...new Set(urls)].filter((u) => /^https?:\/\//.test(u)).slice(0, CAP);
if (!urls.includes(SITE + '/') && !urls.includes(SITE)) urls.unshift(SITE + '/');

// ---- 2. 逐 URL 巡检（顺手收集页面内链接，不额外抓取） ----
const findings = [], times = [];
let ok = 0, broken = 0, slow = 0, slowRechecked = 0, slowFalseAlarms = 0;
const linkSources = new Map();   // 链接 -> 出现在哪些页面

for (const u of urls) {
  const r = await grab(u, 20000);
  if (r.status > 0 && r.status < 400) {
    ok++;
    let bestMs = r.ms;
    // 超阈值 → 复测。时间预算不够时跳过复测，直接按单次结果记（宁可漏报也不拖垮整轮）
    if (r.ms > SLOW && Date.now() - T0 < DEADLINE_MS - 20000) {
      const samples = [r.ms];
      for (let i = 0; i < SLOW_RECHECKS; i++) {
        await sleep(SLOW_RECHECK_GAP);
        const again = await grab(u, 20000);
        if (again.status > 0 && again.status < 400) samples.push(again.ms);
      }
      bestMs = Math.min.apply(null, samples);
      slowRechecked++;
      if (bestMs > SLOW) {
        slow++;
        findings.push({
          finding_type: 'slow_page', url: u, status_code: r.status, response_ms: bestMs,
          detail: '连测 ' + samples.length + ' 次都超过 ' + SLOW + 'ms 阈值（'
            + samples.join(' / ') + 'ms），确实慢',
        });
      } else {
        // 复测后不慢了 = 刚才那下是抖动。不报警，但留个数，免得「为什么没报」成谜
        slowFalseAlarms++;
      }
    } else if (r.ms > SLOW) {
      slow++;
      findings.push({ finding_type: 'slow_page', url: u, status_code: r.status, response_ms: r.ms, detail: '超过 ' + SLOW + 'ms 阈值（时间预算不足，未复测）' });
    }
    // 统计用复测后的最好成绩，才代表这页真实速度；否则一次抖动会把 avg/p95 带歪
    times.push(bestMs);
    if (r.body) {
      for (const item of extractLinks(r.body, u)) {
        let rec = linkSources.get(item.u);
        if (!rec) { rec = { pages: new Set(), kind: item.kind }; linkSources.set(item.u, rec); }
        if (item.kind === 'a') rec.kind = 'a';   // 既是链接又是资源时按链接算
        if (rec.pages.size < 20) rec.pages.add(u);
      }
    }
  } else if (RETRYABLE.has(r.status)) {
    rateLimited++;
    extraGap = Math.min(extraGap + 500, 3000);
    await sleep(extraGap);          // 被限速了就当场退让,别继续猛敲
  } else {
    broken++; findings.push({ finding_type: 'broken_link', url: u, status_code: r.status || null, response_ms: r.ms, detail: r.err || ('HTTP ' + r.status) });
  }
}

// ---- 2b. 页面内链接验证 ----
// 站内：任何 >=400 或连不上都算死链。
// 站外：只认硬错误（连不上 / 404 / 410）。403、429、5xx 多半是第三方防爬或临时故障
//       —— accounts.google.com/gsi/client 对爬虫 UA 就返 403，浏览器里完全正常。
const checked = new Set(urls.map(norm));
const linksFound = linkSources.size;

// 优先级：站内链接 > 站内资源 > 站外链接 > (站外资源不验)。
// 站外资源指 CDN 图片之类——一张图会有十几个尺寸变体，数量爆炸(实测单轮 709 个
// 候选里绝大多数是它)，而且 CDN 自己会管。验它们只会挤占预算，把真正重要的
// 站内链接挤到 CAP 之外。
function rank(u) {
  const rec = linkSources.get(u) || {};
  const inS = isInternal(u);
  if (inS && rec.kind === 'a') return 0;
  if (inS) return 1;
  if (rec.kind === 'a') return 2;
  return 3;
}
let candidates = [...linkSources.keys()].filter((u) => !checked.has(norm(u)));
const skippedExternalAssets = candidates.filter((u) => rank(u) === 3).length;
candidates = candidates.filter((u) => rank(u) < 3).sort((a, b) => rank(a) - rank(b));
let linksTruncated = Math.max(0, candidates.length - LINK_CAP);
candidates = candidates.slice(0, LINK_CAP);

let linksChecked = 0;
for (const link of candidates) {
  if (Date.now() - T0 > DEADLINE_MS) {   // 时间预算到，剩下的记成截断，绝不硬超时
    linksTruncated += candidates.length - linksChecked;
    break;
  }
  const inSite = isInternal(link);
  // 限速只对自家站有意义（WP.com）；站外用短间隔，能在同样预算里验更多。
  await sleep((inSite ? LINK_GAP_MS : 120) + (inSite ? extraGap : 0));
  linksChecked++;
  const r = await grab(link, 15000);
  // 站外的 status=0 只有在「域名根本不存在」时才算死链。一时连不上/超时不算——
  // 2026-08-01 实测 telegram.me 被报 status=0，但服务器上直接 curl 是 200，
  // 纯属并发下的偶发超时。而 http://url 那种假地址是 ENOTFOUND，照样抓得到。
  const dnsDead = r.status === 0 && /ENOTFOUND|EAI_AGAIN|ERR_NAME|getaddrinfo/i.test(r.err || '');
  if (RETRYABLE.has(r.status)) {   // 限速/暂时不可用:不判死,当场退让
    rateLimited++;
    if (inSite) extraGap = Math.min(extraGap + 500, 3000);
    continue;
  }
  const dead = inSite
    ? !(r.status > 0 && r.status < 400)
    : (r.status === 404 || r.status === 410 || dnsDead);
  if (!dead) continue;
  const rec = linkSources.get(link) || { pages: new Set() };
  const srcs = [...rec.pages];
  const where = srcs.length
    ? '出现在 ' + srcs.length + ' 个页面，如 ' + srcs.slice(0, 3).join(' / ')
    : '';
  broken++;
  findings.push({
    finding_type: 'broken_link',
    url: String(link).slice(0, 2048),
    status_code: r.status || null,
    response_ms: r.ms,
    detail: [(inSite ? '页面内站内链接' : '页面内站外链接'), (r.err || ('HTTP ' + r.status)), where]
      .filter(Boolean).join(' | '),
  });
}

// ---- 3. 首页品牌校验 ----
const home = await grab(SITE + '/', 20000);
const homepageOk = home.status >= 200 && home.status < 300 && home.body.includes(BRAND);
if (!homepageOk) findings.push({ finding_type: 'homepage_error', url: SITE + '/', status_code: home.status || null, response_ms: home.ms, detail: (home.status >= 200 && home.status < 300) ? '首页未包含品牌名 Barong Yekhna' : ('首页不可达 HTTP ' + home.status) });
if (!sitemapOk) findings.push({ finding_type: 'sitemap_error', url: SITE + '/wp-sitemap.xml', status_code: null, response_ms: null, detail: 'sitemap 拉取或解析失败' });

// ---- 4. 统计 ----
times.sort((a, b) => a - b);
const avg = times.length ? Math.round(times.reduce((s, x) => s + x, 0) / times.length) : null;
const p95 = times.length ? times[Math.min(times.length - 1, Math.floor(times.length * 0.95))] : null;

return [{ json: {
  ingest_url: ingestUrl,
  // links_* / elapsed_ms 只为执行快照留痕：控制台 schema 会忽略这些字段，但改完哨兵
  // 要靠它们判断"确实扫了页面内链接"而不是"根本没扫所以 0 死链"。截断数也在这看得见。
  links_found: linksFound,
  links_checked: linksChecked,
  links_truncated: linksTruncated,
  links_skipped_external_assets: skippedExternalAssets,
  rate_limited: rateLimited,
  slow_rechecked: slowRechecked,
  slow_false_alarms: slowFalseAlarms,
  elapsed_ms: Date.now() - T0,
  payload: {
    run_id: runId,
    status: 'completed',
    summary: { urls_total: urls.length, urls_ok: ok, urls_broken: broken, urls_slow: slow, avg_response_ms: avg, p95_response_ms: p95, sitemap_ok: sitemapOk, homepage_ok: homepageOk },
    findings: findings.slice(0, 200),
  },
} }];
